reference_solution:
def triangle_minimum_total(triangle):
    costs = triangle[-1].copy()
    for row in range(len(triangle) - 2, -1, -1):
        for column in range(row + 1):
            costs[column] = triangle[row][column] + min(costs[column], costs[column + 1])
    return costs[0]

